const CHECKS={
 role:[/(you are|act as|as an? [a-z]+|your role)/,"Gives Claude a role","Tell Claude who to be, e.g. \"You are a support lead\"."],
 context:[/(which is|because|we want|my (team|manager|list)|context|background|i am|we are|our (team|company|client|product)|situation|currently)/,"Supplies context","Add the situation: who you are, what has happened, what Claude can't know."],
 audience:[/(member|head of|team|owner|recruiter|prospective|audience|reader|customer|manager|client|beginner|executive|leadership|stakeholder|user|student)/,"Names the audience","Say who will read or use the output."],
 goal:[/(decide|recommend|we want|goal|so that|purpose|objective|outcome|in order to|success|need to decide|aim)/,"States the goal","Say what the output is for or what a good result achieves."],
 format:[/(list|one page|one line|report|email|message|readme|compare|group|score each|mark|format|bullet|table|json|heading|sections?|markdown|csv|numbered|columns?|words|paragraph)/,"Specifies output format","Ask for a shape: table, bullets, sections, word count."],
 constraint:[/(always|before you|up to \d|keep|stays?|must|do not|don't|never|only|at most|no more than|under \d|maximum|limit|within|exactly|avoid)/,"Sets constraints","Add limits: length, tone, what to leave out."],
 example:[/(example|e\.g\.|for instance|sample|like this)/,"Includes an example","Show one example of the output you want."],
 verify:[/(show the code|so i can check|pass or fail|verify|cite|source|quote|evidence|confirm|validate|double-check|fact-check|check (each|every|the|that|whether))/,"Asks for verification","Ask Claude to quote sources or flag claims it cannot support."],
 unsure:[/(not (shown|stated|supported|covered)|needs an outside|rather than guess|instead of (guess|estimat)|not sure|unsure|don't know|do not know|uncertain|if you (cannot|can't)|say so|unknown|missing|assum|not in the)/,"Handles uncertainty","Tell Claude what to do when information is missing: say so, don't guess."],
 steps:[/(module|workflow|step|first|then|next|finally|stage|phase|1\.|sequence)/,"Breaks work into steps","Lay the work out as ordered steps."],
 delims:[/(<\/?[a-z_]+>|```|"""|---|\[[a-z _]+\])/,"Separates material with delimiters","Wrap pasted material in tags like <document>…</document>."],
 test:[/(pass rate|cases|test|scenario|edge case|expected|acceptance|case \d|try it with)/,"Defines tests","State test cases and what a pass looks like."],
 privacy:[/(replaced by|placeholder|\[name\]|key (stays|must)|privacy|personal|pii|confidential|anonymi|redact|permission|sensitive|consent|access)/,"Addresses privacy or permissions","State what data must be removed, masked or kept out."],
 human:[/(before (you )?commit|show me|wait for my|i will (verify|review)|for me to|manual|human|review|approv|sign[- ]off|escalat|hand ?off|i will check|before sending)/,"Includes human review","Say where a person checks the output before it is used."],
 metric:[/(\d+ (of|to) \d+|how many|number|measure|metric|%|percent|minutes|hours|cost|accuracy|time saved|rate|score|kpi|per (week|month|day))/,"Uses a measurable result","Add a number: time, cost, accuracy, volume."],
 error:[/(missing|skip|incomplete|unavailable|unreadable|negative|flag|unassigned|not stated|error|fail|fallback|retry|goes wrong|breaks|exception|invalid|if .{0,30}(wrong|missing|empty))/,"Plans for failure","Say what happens when input is bad or a step fails."],
 input:[/(notes|above|these|<[a-z]+>|paste|reviews?|tickets?|projects|answers|cv|input|given|attached|below|document|data|file|text|transcript|spreadsheet|csv)/,"Identifies the input","Name the material Claude should work from."],
 iterate:[/(fix (any|the)|cut it|replace|revise|improve|rewrite|instead|change|shorter|more specific|previous|last (answer|response|draft)|keep .{0,30}but)/,"Gives specific revision feedback","Say what to keep, what to change and why."],
 problem:[/(problem|pain|struggl|waste|takes too long|bottleneck|issue|slow|manual|backlog)/,"Defines the problem","State the problem in the customer's terms."],
 price:[/(price|pricing|\$|₹|rs\.?|fee|effort|estimate|budget|days|hours)/,"Estimates effort or price","Give an effort or price estimate."],
 reuse:[/(\{[a-z_]+\}|save as|shared steps|reusable|template|variable|\{\{|\{[a-z_]+\}|placeholder|modul|parameter|every time)/,"Built for reuse","Use placeholders like {customer_name} so it runs again unchanged."],
 model:[/(opus|sonnet|haiku|effort|thinking)/,"Names the model or effort","Say which model or effort level suits the task, and why."],
 search:[/(web search|research|search the web|official|current)/,"Asks for current information from the web","Tell Claude to use web search or research, and which sources count."],
 image:[/(image|screenshot|photo|chart|diagram|scan|receipt|picture)/,"Says what the visual input is","Tell Claude what the image or scan shows and what to read from it."],
 artifact:[/(artifact|interactive|tracker|dashboard|keep and share|i can keep)/,"Asks for something to keep, not a one-off reply","Say you want an artifact you can keep, edit or share."],
 scope:[/(folder|only (move|read|use)|do not (delete|move|send|share|rename)|don't (delete|move|send))/,"Limits what Claude may touch","Name the folder or app, and the actions Claude must not take."],
 codebase:[/(repo|codebase|claude\.md|test suite|commit|diff|module)/,"Grounds the task in the codebase","Name the repo, file or module, and how to prove the change works."],
 doc:[/(checklist|document|readme|instructions|runbook|guide|changelog|version|how to use)/,"Covers documentation","Ask for or include usage notes and a version."]
};
const SKILL_RUBRIC=[
["Correctness",25,"Is everything in the output true and does it do exactly what you asked?","Check every fact, name, number and date against your source. One uncorrected error means Partly at best."],
["Output quality",20,"Is it complete, well organised and ready to use without editing?","Count the edits you would make before using it. None is Yes; a few small ones is Mostly; a rewrite is Barely."],
["Clarity of instructions",15,"Could a stranger paste your prompt and get the same kind of result?","Reread your prompt as if you knew nothing about the task. Anything you had to already know is a gap."],
["Reliability",15,"Does the prompt work again on different input?","Run it on a second and a third input. Good three times is Yes; twice is Mostly; once is Partly."],
["Limits and errors",10,"Does it cope when information is missing or the input is bad?","Try it once with something missing. If Claude says so instead of guessing, that is Yes."],
["Practical usefulness",15,"Would you really send, publish or use this output?","If you would use it today for real work, Yes. If it is only good as a draft, Partly."]];
const LEVELS_OF=[[1,"Yes, fully"],[.8,"Mostly, small gaps"],[.5,"Partly"],[.2,"Barely"],[0,"No"]];
const CRITICAL=["Correctness: the output contains an error I could not fix","Privacy: personal or confidential data was exposed or mishandled","Safety: the output could cause harm if used as is"];
